toolCalls.args:
{"command": "# Create global.json
cat > global.json <<'EOF'
{
  "sdk": {
    "version": "11.0.100-preview.6.26359.118",
    "allowPrerelease": true,
    "rollForward": "latestFeature",
    "paths": [".dotnet", "$host$"]
  }
}
EOF

# Update .gitignore
grep -qxF '.dotnet/' .gitignore 2>/dev/null || printf '\n.dotnet/\n' >> .gitignore

echo "global.json and .gitignore updated"", "description": "Create global.json and update .gitignore"}
